\label{lemma-products-homotopy}
Let $\mathcal{C}$ be a category. Let $T$ be a set. For $t \in T$
let $X_t$, $Y_t$ be simplicial objects of $\mathcal{C}$. Assume
$X = \prod_{t \in T} X_t$ and $Y = \prod_{t \in T} Y_t$ exist.
\begin{enumerate}
\item If $X_t$ and $Y_t$ are homotopy equivalent for all $t \in T$
and $T$ is finite, then $X$ and $Y$ are homotopy equivalent.
\end{enumerate}
For $t \in T$ let $a_t, b_t : X_t \to Y_t$ be morphisms.
Set $a = \prod a_t : X \to Y$ and $b = \prod b_t : X \to Y$.
\begin{enumerate}
\item[(2)] If there exists a homotopy from $a_t$ to $b_t$ for
all $t \in T$, then there exists a homotopy from $a$ to $b$.
\item[(3)] If $T$ is finite and $a_t, b_t : X_t \to Y_t$ for $t \in T$
are homotopic, then $a$ and $b$ are homotopic.
\end{enumerate}

\label{lemma-local-rings-UFD-c1-bijective}
Let $X$ be a locally Noetherian integral scheme. Consider the map
(\ref{equation-c1}) $\Pic(X) \to \text{Cl}(X)$.
The following are equivalent
\begin{enumerate}
\item the local rings of $X$ are UFDs, and
\item $X$ is normal and $\Pic(X) \to \text{Cl}(X)$
is surjective.
\end{enumerate}
In this case $\Pic(X) \to \text{Cl}(X)$ is an isomorphism.

\label{lemma-tor-strictly-pro-zero}
\begin{reference}
This is \cite[Lemma 9.9]{quillenhomology}; note that
the author forgot the word ``strict'' in the statement
although it was clearly intended.
\end{reference}
Let $A$ be a Noetherian ring. Let $I$ be an ideal of $A$.
Let $M$ be a finite $A$-module. For every $p > 0$ there exists a $c > 0$
such that $\text{Tor}_p^A(M, A/I^n) \to \text{Tor}_p^A(M, A/I^{n - c})$
is zero for all $n \geq c$.

